words = %w[apple bob cat avocado banana cherry bob]

p words.tally                       # {"apple" => 1, "bob" => 2, "cat" => 1, ...}
p words.group_by(&:size)            # {5 => ["apple"], 3 => ["bob", "cat", "bob"], ...}
short, long = words.partition { it.size <= 3 }
p short                             # ["bob", "cat", "bob"]

index = words.uniq.each_with_object(Hash.new { |h, k| h[k] = [] }) do |w, h|
  h[w[0]] << w
end
p index["a"]                        # ["apple", "avocado"]

p words.uniq.sort_by { [-it.size, it] }.first(2)   # ["avocado", "banana"]
p (1..10).reduce(:*)                # 3628800
p [1, nil, 3].filter_map { it && it * 2 }  # [2, 6]
p words.map.with_index(1) { |w, i| "#{i}.#{w}" }.first(2)  # ["1.apple", "2.bob"]
prices = { tea: 3, cake: 5 }
p prices.transform_values { it * 2 }   # {tea: 6, cake: 10}
p prices.sum { |_, v| v }              # 8

require "benchmark"

slow_io = -> { sleep 0.2; :ok }
t = Benchmark.realtime { 5.times.map { Thread.new(&slow_io) }.each(&:join) }
puts "5 sleeps in parallel: #{t.round(1)}s"      # ~0.2s, not 1.0s

counter = 0
lock = Mutex.new
10.times.map {
  Thread.new { 10_000.times { lock.synchronize { counter += 1 } } }
}.each(&:join)
p counter                                        # 100000

queue = Queue.new
workers = 3.times.map do |i|
  Thread.new do
    while (job = queue.pop) != :stop
      puts "worker #{i} squared #{job} = #{job * job}"
    end
  end
end
[2, 3, 4].each { queue << it }
3.times { queue << :stop }
workers.each(&:join)
